  Lemma ffsh_client_range : forall LB LF k ff fp SP a n,
    fresh_frame H LF k ff fp -> Z.shiftr ff 3 + 2147450880 <= a -> a + n <= Z.shiftr ff 3 + 2147450880 + fshn k -> aclient_range H LB SP a n.
  Proof.
    intros LB LF k ff fp SP a n FF H1 H2.
    pose proof (ff_facts _ _ _ _ _ FF) as (K0 & FP & NP & E8 & F1 & F2 & F3 & F3' & F4 & F5 & F6 & F7 & F8 & F9 & F10 & F11 & F12 & APF & APP1 & SS & SF1 & SF2 & SF3 & NSB).
    pose proof (ff_sh_in_fsb _ _ _ _ FF) as (S1 & S2). rewrite SS in *.
    right; right; right; right; right; left. lia.
  Qed.
Scheme kc__2 := Elimination for Corelib.Init.Logic.or Sort Prop.

  (* [comment removed for export] *)
  Lemma xpres_drop_fresh : forall s' LB m0 p A n SP X m m',
    as_RHEAP H s' ((p, A, n) :: LB) m0 -> aceil <= SP ->
